#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int ngoai = 0;
    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);
        if (t < 60 || t > 90) ngoai++;
    }
    printf("%d\n", ngoai);
    return 0;
}
